#!/usr/bin/env python3
# 수업 노트 붙이기 + 검사.  python3 check.py <job.json> <작업 폴더>
#   작업 폴더 : b*.part (본문, 이름순으로 붙인다) · task-1.part, task-2.part … (반마다 과제물 상자, 없으면 빈칸)
#   job.json  : {"videoId","lastSecond","breaks":[[시작초,끝초],…],"targets":[{"className","week","short","assignmentTotal"}]}
#   결과      : <작업 폴더>/out/[수업노트] <반명> <N>회차.html   · 하나라도 어긋나면 exit 1
import sys, os, re, json, glob
from html.parser import HTMLParser

here = os.path.dirname(os.path.abspath(__file__))
job = json.load(open(sys.argv[1], encoding='utf-8'))
work = sys.argv[2]
errs = []
def bad(m): errs.append(m)

head = open(os.path.join(here, 'head.part'), encoding='utf-8').read()
parts = sorted(glob.glob(os.path.join(work, 'b*.part')))
if not parts: sys.exit('본문(b*.part)이 없습니다')
body = ''.join(open(p, encoding='utf-8').read() for p in parts)
vid = job['videoId']; last = int(job['lastSecond']); breaks = [(int(a), int(b)) for a, b in job.get('breaks', [])]
css = head[head.index('<style>'):head.index('</style>')]
css_classes = set(re.findall(r'\.([A-Za-z_][\w-]*)', re.sub(r'url\([^)]*\)', '', css)))
VOID = {'br', 'hr', 'img', 'meta', 'link', 'input', 'col', 'wbr'}

def secs(label):
    p = [int(x) for x in label.split(':')]
    return p[0] * 60 + p[1] if len(p) == 2 else p[0] * 3600 + p[1] * 60 + p[2]
def hm(s): return '%d:%02d' % (s // 3600, s // 60 % 60)

class Bal(HTMLParser):
    def __init__(s): super().__init__(convert_charrefs=True); s.st = []; s.cls = set(); s.text = []
    def handle_starttag(s, t, a):
        for k, v in a:
            if k == 'class' and v: s.cls.update(v.split())
        if t not in VOID: s.st.append((t, s.getpos()[0]))
    def handle_endtag(s, t):
        if t in VOID: return
        if not s.st or s.st[-1][0] != t: bad('태그 짝이 안 맞음 : </%s> (줄 %d) · 열려 있는 것 %s' % (t, s.getpos()[0], s.st[-1] if s.st else '없음')); return
        s.st.pop()
    def handle_data(s, d): s.text.append(d)

def check(html, t, name):
    n0 = len(errs)
    if re.search(r'[\u200b-\u200f\u00a0\ufeff\u2028\u2029\u00ad]', html): bad('보이지 않는 글자가 들어 있음')
    if '{{' in html or '}}' in html: bad('채우지 않은 자리({{ }})가 남아 있음')
    for ph in ('(강의 제목)', '(절 제목)', '(영상번호)', '(단원)', '(개념 설명)', '(…)'):
        if ph in html: bad('뼈대의 자리 글자가 남아 있음 : ' + ph)
    b = Bal(); b.feed(html)
    if b.st: bad('닫지 않은 태그 : %s' % b.st[-3:])
    if 'say' in b.cls: bad('class="say" (선생님 말씀 상자)를 쓰면 안 됨')
    miss = sorted(c for c in b.cls if c not in css_classes)
    if miss: bad('머리 CSS 에 없는 class : ' + ', '.join(miss))
    for need in ('top', 'eyebrow', 'sub', 'meta', 'sum', 'chk', 'foot', 'card'):
        if need not in b.cls: bad('빠진 부분 : .' + need)
    if html.count('<h1>') != 1: bad('h1 은 하나')
    # 절 번호 01 부터 빠짐없이 · 절마다 시간표 · 시간이 뒤로 가지 않게
    h2 = re.findall(r'<h2>(.*?)</h2>', html, re.S)
    nums = [re.search(r'^<span class="n">(\d\d)</span>', x) for x in h2]
    if len(h2) < 3: bad('절(h2)이 3개 미만')
    if any(m is None for m in nums) or [m.group(1) for m in nums if m] != ['%02d' % (i + 1) for i in range(len(h2))]:
        bad('절 번호가 01 부터 차례로 이어지지 않음 : %s' % [m.group(1) if m else '?' for m in nums])
    prev = -1
    for i, x in enumerate(h2):
        m = re.search(r'\?t=(\d+)"', x)
        if not m: bad('%02d절 제목에 시간표가 없음' % (i + 1)); continue
        if int(m.group(1)) < prev: bad('%02d절 시간표가 앞 절보다 이름' % (i + 1))
        prev = int(m.group(1))
    # 시간표 : 글자 = 초 · 그 영상 · 영상 길이 안 · 쉬는 구간 밖
    links = re.findall(r'<a class="t"[^>]*>.*?</a>', html, re.S)
    good = re.findall(r'<a class="t" href="https://youtu\.be/([A-Za-z0-9_-]{11})\?t=(\d+)" target="_blank">(\d{1,2}:\d\d(?::\d\d)?)</a>', html)
    if len(links) != len(good): bad('모양이 다른 시간표가 %d개 있음 (<a class="t" href="https://youtu.be/<번호>?t=<초>" target="_blank">h:mm:ss</a>)' % (len(links) - len(good)))
    if len(re.findall(r'<a\b', html)) != len(links): bad('시간표가 아닌 링크가 있음')
    for v, s, lab in good:
        s = int(s)
        if v != vid: bad('다른 영상 번호 : ' + v)
        if secs(lab) != s: bad('시간표 글자와 초가 다름 : %s ≠ t=%d' % (lab, s))
        if any(int(x) > 59 for x in lab.split(':')[1:]): bad('시간표 글자가 이상함 : ' + lab)
        if s > last: bad('영상 길이를 넘는 시간표 : ' + lab)
        if any(a < s < e for a, e in breaks): bad('쉬는 구간을 가리키는 시간표 : ' + lab)
    if len(good) < len(h2): bad('시간표가 절 수보다 적음')
    if re.search(r'</a>\s*[.,]', html): bad('링크 바로 뒤에 마침표·쉼표가 있음 (인쇄 때 링크가 숨는다 → 마침표를 링크 앞으로)')
    text = ''.join(b.text)
    for a, e in breaks:
        lab = hm(a) + '~' + hm(e)
        if text.count(lab) < 2: bad('쉬는 구간 %s 을 머리 카드와 맺음말 두 곳에 밝혀야 함' % lab)
    if t['className'] not in text or ('%d회차' % t['week']) not in text: bad('반 이름·회차가 본문에 없음')
    tot = int(t.get('assignmentTotal') or 0)
    if tot and not re.search(r'과제물\s*%d\s*문항' % tot, text): bad('과제물 상자에 "과제물 %d문항" 이 없음' % tot)
    if len(text) < 6000: bad('본문이 너무 짧음 (%d자)' % len(text))
    print('%s  %s  · %d자 · 절 %d · 시간표 %d' % ('통과' if len(errs) == n0 else '실패', name, len(html), len(h2), len(good)))

os.makedirs(os.path.join(work, 'out'), exist_ok=True)
for i, t in enumerate(job['targets']):
    tp = os.path.join(work, 'task-%d.part' % (i + 1))
    task = open(tp, encoding='utf-8').read() if os.path.exists(tp) else ''
    if int(t.get('assignmentTotal') or 0) and not task.strip(): bad('task-%d.part (과제물 상자)가 없음' % (i + 1))
    title = '수업 노트 · %s %d회차' % (t.get('short') or t['className'], t['week'])
    html = head.replace('{{TITLE}}', title) + body.replace('{{TASKBOX}}', task.strip()).replace('{{CLASS}}', t['className']).replace('{{WEEK}}', str(t['week']))
    if body.count('{{TASKBOX}}') != 1: bad('본문에 {{TASKBOX}} 가 정확히 한 번 있어야 함')
    name = '[수업노트] %s %d회차.html' % (t['className'], t['week'])
    if re.search(r'[\\/:*?"<>|]', name): bad('파일 이름에 쓸 수 없는 글자 : ' + name)
    check(html, t, name)
    open(os.path.join(work, 'out', name), 'w', encoding='utf-8', newline='\n').write(html)
if errs:
    print('\n고칠 것 %d건' % len(errs)); [print(' - ' + e) for e in dict.fromkeys(errs)]; sys.exit(1)
print('모두 통과')

