// 수업 노트 PDF 뽑기 + 화면 검사.  node shot.js <out 폴더>
//   폴더 안의 .html 마다 : 자바스크립트 오류 0 · 가로 넘침 0px (390 / 880 / 인쇄) → 같은 이름 .pdf (A4). 하나라도 어긋나면 exit 1
const { chromium } = require('playwright'); const fs = require('fs'); const path = require('path'); const url = require('url');
(async () => {
  const dir = path.resolve(process.argv[2]); const files = fs.readdirSync(dir).filter(f => f.endsWith('.html')).sort();
  if (!files.length) { console.log('html 이 없습니다'); process.exit(1); }
  const browser = await chromium.launch(); let bad = 0;
  for (const f of files) {
    const page = await browser.newPage({ viewport: { width: 880, height: 1200 } }); const errs = [];
    page.on('pageerror', e => errs.push(String(e))); page.on('console', m => { if (m.type() === 'error' && !/net::|Failed to load resource/.test(m.text())) errs.push(m.text()); });
    await page.route('**/*', r => r.request().url().startsWith('file:') ? r.continue() : r.abort());   // 바깥(글꼴 서버)은 막는다 — 설치된 글꼴로 그린다
    await page.goto(url.pathToFileURL(path.join(dir, f)).href, { waitUntil: 'load' });
    await page.addStyleTag({ content: 'body{font-family:"Noto Sans CJK KR","Noto Sans KR",sans-serif!important}' });
    const over = async () => page.evaluate(() => { const d = document.documentElement; let w = 0; for (const e of document.querySelectorAll('body *')) { const r = e.getBoundingClientRect(); if (r.width && r.right - d.clientWidth > w) w = r.right - d.clientWidth; } return Math.max(Math.ceil(w), d.scrollWidth - d.clientWidth); });
    const res = {};
    for (const w of [390, 880]) { await page.setViewportSize({ width: w, height: 1200 }); res['w' + w] = await over(); }
    await page.emulateMedia({ media: 'print' }); await page.setViewportSize({ width: 703, height: 1000 }); res.print = await over();   // A4 − 여백 24mm ≈ 703px
    const pdf = path.join(dir, f.replace(/\.html$/, '.pdf'));
    await page.pdf({ path: pdf, format: 'A4', printBackground: true, preferCSSPageSize: true });
    const kb = Math.round(fs.statSync(pdf).size / 1024);
    const ok = !errs.length && !res.w390 && !res.w880 && !res.print && kb > 20;
    if (!ok) bad++;
    console.log((ok ? '통과' : '실패') + '  ' + f + '  · 넘침 390:' + res.w390 + ' 880:' + res.w880 + ' 인쇄:' + res.print + 'px · 오류 ' + errs.length + ' · PDF ' + kb + 'KB' + (errs.length ? '\n   ' + errs.slice(0, 3).join('\n   ') : ''));
    await page.close();
  }
  await browser.close(); console.log(bad ? '고칠 것 ' + bad + '건' : '모두 통과'); process.exit(bad ? 1 : 0);
})();
